-- Worker logs for the VictoriaLogs gallery source, generated by ClickHouse and
-- sent to VictoriaLogs' JSON lines endpoint by provision.ts. Same day curve and
-- incident window as gallery.http_requests.
SELECT
    concat(replaceOne(toString(minute + toIntervalMillisecond(rand(1) % 60000), 'UTC'), ' ', 'T'), 'Z') AS timestamp,
    workers[w].1 AS service,
    'prod' AS env,
    workers[w].2 AS namespace,
    concat(service, '-', ['7d9f4', '7d9f4', 'b62c1'][1 + rand(2) % 3], '-', ['x2kqp', 'm8rzt', 'q4vnw'][1 + rand(3) % 3]) AS pod,
    multiIf(pl < perr, 'error', pl < perr + 0.06, 'warn', 'info') AS level,
    toUInt32(workers[w].3 * exp(randNormal(0, 0.5, 4)) * if(incident = 1 AND w = 4, 5, 1)) AS duration_ms,
    multiIf(
        level = 'error' AND w = 4, ['webhook signature check failed: clock skew', 'gateway callback timed out after 10 s', 'payment state machine rejected transition captured -> authorized'][1 + rand(5) % 3],
        level = 'error', ['retry budget exhausted', 'downstream returned 503', 'dead-lettered message after 5 attempts'][1 + rand(5) % 3],
        level = 'warn', ['slow consumer, lag above 2000 messages', 'retrying after transient error', 'cache miss storm, falling back to database'][1 + rand(6) % 3],
        workers[w].4
    ) AS message
FROM
(
    SELECT
        minute,
        incident,
        rand(7) % 100 AS pw,
        arrayFirstIndex(c -> c > pw, [30, 52, 70, 86, 100]) AS w,
        randCanonical(8) AS pl,
        multiIf(incident = 1 AND w = 4, 0.38, incident = 2 AND w = 5, 0.12, 0.012) AS perr,
        [('invoice-worker', 'billing', 85, 'invoice rendered'),
         ('notification-worker', 'messaging', 40, 'notification delivered'),
         ('inventory-worker', 'catalog', 220, 'stock levels synced'),
         ('payment-webhooks', 'payments', 160, 'payment webhook handled'),
         ('ledger-writer', 'finance', 300, 'ledger batch committed')] AS workers
    FROM
    (
        SELECT
            minute,
            multiIf(ago BETWEEN 200 AND 228, 1, ago BETWEEN 4300 AND 4330, 2, 0) AS incident,
            toUInt32(36 * (0.55 - 0.45 * cos(2 * pi() * (hour - 4) / 24)) * (1 + 0.06 * sin(2.7 * toRelativeDayNum(minute, 'Asia/Kolkata'))) * (0.9 + 0.2 * randCanonical(9))) AS n
        FROM
        (
            SELECT
                toStartOfMinute(now()) - toIntervalMinute(number + 1) AS minute,
                number + 1 AS ago,
                toHour(minute, 'Asia/Kolkata') + toMinute(minute, 'Asia/Kolkata') / 60 AS hour
            FROM numbers(10000)
        )
    )
    ARRAY JOIN range(n) AS i
)
FORMAT JSONEachRow
